import{_ as i,b as s,c as a,g as l}from"./chunks/framework.86O3EbG5.js";const c=JSON.parse('{"title":"从零构建大模型（五）","description":"","frontmatter":{"title":"从零构建大模型（五）","subTitle":"在无标签数据上进行预训练","author":"oasis","tags":["llm"]},"headers":[],"relativePath":"articles/artificial-intelligence/books/build-a-llm/5.md","filePath":"articles/artificial-intelligence/books/build-a-llm/5.md"}'),o={name:"articles/artificial-intelligence/books/build-a-llm/5.md"};function e(p,t,n,h,u,k){return s(),a("div",null,[...t[0]||(t[0]=[l(`<h2 id="模型评估" tabindex="-1">模型评估</h2><p>模型评估主要围绕 损失值 这个概念展开。损失值将作为训练进展和成功的衡量标准。而训练大语言模型的目标是最大化正确词元的可能性，也就是最大化与目标词元对应的 softmax 概率值。</p><p>通过更新模型权重，可以最大化与目标词元对应的 softmax 概率值。权重更新是通过一种称为反向传播的过程完成的。反向传播需要一个损失函数（计算模型的预测输出与实际期望输出之间的差异）。 这个损失函数衡量的是模型的预测与目标值之间的偏差。</p><p>文本生成损失的计算逻辑：</p><ol><li>logits</li><li>概率</li><li>目标概率</li><li>对数概率</li><li>平均对数概率</li><li>负平均对数概率</li></ol><p>模型的评估主要体现在负平均对数概率，在深度学习中，通常的做法是将负平均对数概率降至 0。</p><p>交叉熵损失用于衡量两个概率分布之间的差异——通常是标签（数据集中的词元）的真是分布和模型生成的预测分布之间的差异。</p><p>困惑度可以衡量模型预测的概率分布与数据集中实际词汇分布的匹配程度。与损失类似，较低的困惑度表明模型的预测更接近实际分布。困惑度实际表示了模型不确定在词汇表的N个词元中应该生成哪个来作为下一个词元。这样的方式更容易解释。</p><p>本书中先设计了衡量的方法，这很值的借鉴，就像在实际开发中，先编写测试用例，才能以目标为导向的走下去。</p><h2 id="训练-llm" tabindex="-1">训练 LLM</h2><p>此书中实现了简单的训练循环。首先需要将数据分成：训练集和验证集。书中采用了 90% 的数据进行训练，10% 的作为验证数据。</p><p>分块和批次在训练循环中的所指，可参考下面的例子：</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">文本 = &quot;深度学习让计算机能够理解人类语言。人工智能正在改变世界。&quot;</span></span></code></pre></div><p>分词：</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">分词后 = [&quot;深度&quot;, &quot;学习&quot;, &quot;让&quot;, &quot;计算机&quot;, &quot;能够&quot;, &quot;理解&quot;, &quot;人类&quot;, &quot;语言&quot;, &quot;。&quot;, </span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">         &quot;人工&quot;, &quot;智能&quot;, &quot;正在&quot;, &quot;改变&quot;, &quot;世界&quot;, &quot;。&quot;]</span></span></code></pre></div><p>分块（块大小=6）</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">块1: [&quot;深度&quot;, &quot;学习&quot;, &quot;让&quot;, &quot;计算机&quot;, &quot;能够&quot;, &quot;理解&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">块2: [&quot;人类&quot;, &quot;语言&quot;, &quot;。&quot;, &quot;人工&quot;, &quot;智能&quot;, &quot;正在&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">块3: [&quot;改变&quot;, &quot;世界&quot;, &quot;。&quot;, &quot;&lt;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#B31D28;--shiki-dark-font-style:italic;">填充</span><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">&gt;&quot;, &quot;&lt;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#B31D28;--shiki-dark-font-style:italic;">填充</span><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">&gt;&quot;, &quot;&lt;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#B31D28;--shiki-dark-font-style:italic;">填充</span><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">&gt;&quot;]</span></span></code></pre></div><p>分批（批次大小=2）</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-light vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">批次1: [块1, 块2]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">批次2: [块3, &lt;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#B31D28;--shiki-dark-font-style:italic;">空块</span><span style="--shiki-light:#24292E;--shiki-dark:#24292E;">&gt;]</span></span></code></pre></div><h2 id="解码策略-文本生成策略" tabindex="-1">解码策略（文本生成策略）</h2><p>之所以引入解码策略，是因为生成的词元是从词汇表的所有词元中选择概率分数最大的那一个，这样即使在相同的起始上下文中多次运行前面的生成函数，大语言模型将始终生成相同的输出。</p><p>下面有两种算法可以让生成的文本更有原创性：</p><ol><li>温度缩放：在下一个词元生成任务中添加概率选择过程的技术。温度缩放指的是将 logits 除以一个大于 0 的数。</li><li>Top-k采样：其目的是解决温度缩放下可能导致的语法不正确或完全无意义的输出。在 Top-k 采样中，可以将采样的词元限制在前 K 个最可能的词元上，并通过掩码概率分数的方式来排除其他词元。</li></ol><p>Top-k 采样像编译器的词法分析器向前看 k 个 Token。 在生成文本函数的中先应用 Top-k 采样，然后在通过温度缩放，确定下一个词元。</p><h2 id="加载和保存权重" tabindex="-1">加载和保存权重</h2><p>模型的训练耗时耗资源，因此本地化模型权重就变得很重要。在 PyTorch 中通过 save 方法可以保存模型的 state_dict。文件扩展名为 <code>.pth</code></p><p>既然可以本地化模型的 state_dict，那么应该有对应的加载方法。</p>`,27)])])}const q=i(o,[["render",e]]);export{c as __pageData,q as default};
